     */
    public function useInteresadosQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinInteresados($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'Interesados', 'InteresadosQuery');
    }

